catalog_script_client.script:
function onSubmit() {
    g_form.hideFieldMsg('contact_full_name', true)
    g_form.hideFieldMsg('contact_email', true)
    g_form.hideFieldMsg('contact_number', true)

    // Patrons already have a user record, so their contact details are optional.
    if (!isGuestSubmitter()) return true

    var fullName = clean(g_form.getValue('contact_full_name'))
    var email = clean(g_form.getValue('contact_email'))
    var number = clean(g_form.getValue('contact_number'))
    var blocked = false

    if (!fullName) {
        g_form.showFieldMsg('contact_full_name', 'Please tell us your full name so we can hold the car for you.', 'error', true)
        blocked = true
    }

    if (!email) {
        g_form.showFieldMsg('contact_email', 'Please enter an email address we can send the confirmation to.', 'error', true)
        blocked = true
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        g_form.showFieldMsg('contact_email', 'Please enter a valid email address, for example name@example.com.', 'error', true)
        blocked = true
    }

    if (!number) {
        g_form.showFieldMsg('contact_number', 'Please enter a contact number we can reach you on.', 'error', true)
        blocked = true
    } else if (!/^[0-9+()\-.\s]{6,}$/.test(number)) {
        g_form.showFieldMsg('contact_number', 'Please enter a contact number using digits only (spaces, +, - and brackets are allowed).', 'error', true)
        blocked = true
    }

    if (blocked) {
        g_form.addErrorMessage('Guest reservations need your name, email address and contact number.')
        return false
    }

    return true

    /**
     * Decides whether the submitter is a transient guest - purely client side,
     * because onSubmit cannot wait for an asynchronous GlideAjax callback.
     *
     * Primary source: the read-only "submitter_type" variable, whose default is
     * evaluated on the server when the form renders.
     * Fallback: the session user exposed on g_user - unauthenticated Service
     * Portal sessions run as the platform "guest" user.
     */
    function isGuestSubmitter() {
        var declared = clean(g_form.getValue('submitter_type')).toLowerCase()
        if (declared === 'guest') return true
        if (declared === 'patron') return false

        if (typeof g_user === 'undefined' || !g_user) return false

        var userName = String(g_user.userName || '').toLowerCase()
        var userId = String(g_user.userID || '').toLowerCase()
        return !userId || userName === 'guest' || userId === 'guest'
    }

    function clean(value) {
        return String(value === null || typeof value === 'undefined' ? '' : value).replace(/^\s+|\s+$/g, '')
    }
}
